export default function Home(){
 const [page,setPage]=useState<Page>("items"),[query,setQuery]=useState(""),[counts,setCounts]=useState<Bag>({}),[doneQuests,setDoneQuests]=useState<Checks>({}),[doneModules,setDoneModules]=useState<Checks>({}),[doneStory,setDoneStory]=useState<Checks>({}),[ready,setReady]=useState(false);
 useEffect(()=>{try{setCounts(JSON.parse(localStorage.getItem("tarkov-counts")||"{}"));const oldQuests:Checks=JSON.parse(localStorage.getItem("tarkov-quests")||"{}"),oldModules:Checks=JSON.parse(localStorage.getItem("tarkov-modules")||"{}");setDoneQuests(Object.fromEntries(Object.entries(oldQuests).map(([id,value])=>[(progress.legacyQuestIds as Record<string,string>)[id]||id,value])));setDoneModules(Object.fromEntries(Object.entries(oldModules).map(([id,value])=>[(progress.legacyModuleIds as Record<string,string>)[id]||id,value])));setDoneStory(JSON.parse(localStorage.getItem("tarkov-story")||"{}"))}catch{}setReady(true)},[]);
 useEffect(()=>{if(!ready)return;localStorage.setItem("tarkov-counts",JSON.stringify(counts));localStorage.setItem("tarkov-quests",JSON.stringify(doneQuests));localStorage.setItem("tarkov-modules",JSON.stringify(doneModules));localStorage.setItem("tarkov-story",JSON.stringify(doneStory))},[counts,doneQuests,doneModules,doneStory,ready]);
 useEffect(()=>{const reset=(event:Event)=>{const target=(event as CustomEvent<string>).detail;if(target==="quests"){if(window.confirm("クエストの完了状況をすべてリセットします。\nメインクエストとサブクエストのチェックがすべて外れ、必要アイテム数が初期状態に戻ります。\n\n本当にリセットしますか？")){setDoneQuests({});setDoneStory({})}}else if(target==="owned"){if(window.confirm("入力・取込した所持アイテム数をすべて0に戻します。\nクエストの完了状況とハイドアウトの設備レベルは変更されません。\n\n本当に所持数をリセットしますか？"))setCounts({})}else if(target==="hideout-levels"&&window.confirm("ハイドアウトの設備レベルをすべてリセットします。\n全設備が「未建設」に戻り、必要アイテム数が初期状態に戻ります。\n所持アイテム数は変更されません。\n\n本当に設備レベルをリセットしますか？"))setDoneModules({})};window.addEventListener("ledger-reset",reset);return()=>window.removeEventListener("ledger-reset",reset)},[]);
 useEffect(()=>{const valid=(value:any):value is Page=>["items","quests","hideout","guide","maps","sellcheck"].includes(value);if(!valid(history.state?.stashPage))history.replaceState({...history.state,stashPage:"items"},"");const restore=(event:PopStateEvent)=>{if(valid(event.state?.stashPage)){setPage(event.state.stashPage);setQuery("")}};window.addEventListener("popstate",restore);return()=>window.removeEventListener("popstate",restore)},[]);
 const req=useMemo(()=>{const q:Bag={},h:Bag={};for(const task of progress.quests)if(!doneQuests[task.id])for(const x of task.items)q[x.id]=(q[x.id]||0)+x.count;for(const m of progress.modules)if(!doneModules[m.id])for(const x of m.items)h[x.id]=(h[x.id]||0)+x.count;return{q,h}},[doneQuests,doneModules]);
 const totals=items.reduce((a,i)=>({q:a.q+(req.q[i.id]||0),h:a.h+(req.h[i.id]||0)}),{q:0,h:0});
 const ownership=items.reduce((a,i)=>{const need=(req.q[i.id]||0)+(req.h[i.id]||0),have=counts[i.id]||0;a.applied+=Math.min(need,have);a.shortage+=Math.max(0,need-have);if(need>0&&have>=need)a.complete++;return a},{applied:0,shortage:0,complete:0});
 const visible=items.filter(i=>((req.q[i.id]||0)+(req.h[i.id]||0)>0)&&`${i.name} ${i.shortName}`.toLowerCase().includes(query.toLowerCase()));
 const setStationLevel=(station:string,level:number)=>setDoneModules(old=>{const next={...old};for(const m of progress.modules.filter(x=>x.station===station))next[m.id]=m.level<=level;return next});
 const openPage=(next:Page)=>{if(next!==page){let state:any={...history.state,stashPage:next};if(next==="guide"){try{const last=JSON.parse(sessionStorage.getItem("tarkov-task-last-view")||"{}");state={...state,guideView:last.guideView||"traders",guideSelected:last.selected||"",guideTrader:last.selectedTrader||""}}catch{state={...state,guideView:"traders",guideSelected:"",guideTrader:""}}}if(next==="maps"){try{const last=JSON.parse(sessionStorage.getItem("tarkov-map-last-view")||"{}");state={...state,mapStage:last.selected||""}}catch{state={...state,mapStage:""}}}history.pushState(state,"")}setPage(next);setQuery("")};
 return <main><header className="hero compact"><div className="eyebrow">ESCAPE FROM TARKOV · PROGRESSION LEDGER</div><div className="heroRow"><div><h1>STASH <span>LEDGER</span></h1><p>進行状況と所持数から、不足アイテムを自動計算。</p></div><div className="totalSummary ownershipSummary"><div className="questTotal"><span>QUEST</span><strong>{totals.q}</strong><small>クエスト必要総数</small></div><div className="hideoutTotal"><span>HIDEOUT</span><strong>{totals.h}</strong><small>ハイドアウト必要総数</small></div><div className="ownedTotal"><span>OWNED / APPLIED</span><strong>{ownership.applied}</strong><small>必要数に使える所持品</small></div><div className="shortageTotal"><span>SHORTAGE</span><strong>{ownership.shortage}</strong><small>現在の不足総数</small></div></div></div></header>
 <nav className="mainNav">{([['items','アイテム'],['quests','クエスト'],['hideout','ハイドアウト'],['guide','タスク情報'],['maps','MAP'],['sellcheck','売却チェック']] as const).map(([k,l],index)=><button className={page===k?"active":""} onClick={()=>openPage(k)} key={k}><span>0{index+1}</span>{l}</button>)}</nav>
 {page==="items"&&<ItemPage query={query} setQuery={setQuery} visible={visible} req={req} counts={counts} setCount={(id,n)=>setCounts(c=>({...c,[id]:Math.max(0,n)}))}/>} 
 {page==="quests"&&<QuestPage query={query} setQuery={setQuery} done={doneQuests} setDone={setDoneQuests} storyDone={doneStory} setStoryDone={setDoneStory}/>} 
 {page==="hideout"&&<HideoutWorkspace query={query} setQuery={setQuery} done={doneModules} setLevel={setStationLevel} counts={counts} applyCounts={(found,mode)=>setCounts(old=>{const next={...old};for(const[id,n]of Object.entries(found))next[id]=mode==='add'?(next[id]||0)+n:n;return next})}/>} 
 {page==="guide"&&<TaskGuidePage done={doneQuests} setDone={setDoneQuests}/>} 
 {page==="maps"&&<MapHub/>}
 {page==="sellcheck"&&<SellCheckPage req={req}/>} 
 <footer>DATA: TARKOVDATA · LOCAL SAVE <span>クエストとハイドアウト設定はこのPCに自動保存されます</span></footer></main>
}

type ScanHit={id:string;count:number;confidence:number};
function loadImage(src:string){return new Promise<HTMLImageElement>((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
function imageFeature(source:CanvasImageSource,sx:number,sy:number,sw:number,sh:number,w:number,h:number){const c=document.createElement("canvas");c.width=w;c.height=h;const x=c.getContext("2d",{willReadFrequently:true})!;x.drawImage(source,sx,sy,sw,sh,0,0,w,h);return x.getImageData(0,0,w,h).data}
function featureMse(a:Uint8ClampedArray,b:Uint8ClampedArray,w:number,h:number){let sum=0,n=0;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const p=(y*w+x)*4;for(let c=0;c<3;c++){const d=a[p+c]-b[p+c];sum+=d*d;n++}}return sum/Math.max(1,n)}
function regionMse(grid:Uint8ClampedArray,gridWidth:number,template:Uint8ClampedArray,startX:number,startY:number,w:number,h:number){let sum=0,n=0;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const gp=((startY+y)*gridWidth+startX+x)*4,tp=(y*w+x)*4;for(let c=0;c<3;c++){const d=grid[gp+c]-template[tp+c];sum+=d*d;n++}}return sum/Math.max(1,n)}
function cellDeviation(grid:Uint8ClampedArray,col:number,row:number){let sum=0,squares=0,n=0;for(let y=2;y<14;y++)for(let x=2;x<14;x++)for(let c=0;c<3;c++){const v=grid[((row*16+y)*224+col*16+x)*4+c];sum+=v;squares+=v*v;n++}const mean=sum/n;return Math.sqrt(Math.max(0,squares/n-mean*mean))}
function cellDeviationAt(grid:Uint8ClampedArray,gridWidth:number,col:number,row:number){let sum=0,squares=0,n=0;for(let y=2;y<14;y++)for(let x=2;x<14;x++)for(let c=0;c<3;c++){const v=grid[((row*16+y)*gridWidth+col*16+x)*4+c];sum+=v;squares+=v*v;n++}const mean=sum/n;return Math.sqrt(Math.max(0,squares/n-mean*mean))}

function ScanPage({counts,applyCounts}:{counts:Bag;applyCounts:(found:Bag,mode:"replace"|"add")=>void}){
 const input=useRef<HTMLInputElement>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[hits,setHits]=useState<ScanHit[]>([]),[fileCount,setFileCount]=useState(0);
 const hideoutIds=useMemo(()=>new Set(progress.modules.flatMap(module=>module.items.map(item=>item.id))),[]),hideoutItems=useMemo(()=>items.filter(item=>hideoutIds.has(item.id)),[hideoutIds]);
 const analyze=async(files:File[])=>{const images=files.filter(f=>f.type.startsWith("image/"));if(!images.length)return;setBusy(true);setMessage("画像とアイテム画像を照合しています…");setHits([]);try{
   const templates=await Promise.all(hideoutItems.map(async item=>{const img=await loadImage(asset(`items/${item.id}.webp`));const cols=Math.max(1,Math.round(img.naturalWidth/64)),rows=Math.max(1,Math.round(img.naturalHeight/64)),w=cols*16,h=rows*16;return{item,cols,rows,w,h,feature:imageFeature(img,0,0,img.naturalWidth,img.naturalHeight,w,h)}}));
   const totals:Record<string,{count:number;confidence:number}>={};
   for(const file of images){const bitmap=await createImageBitmap(file),scaleX=bitmap.width/1920,scaleY=bitmap.height/1080,originX=518.25*scaleX,originY=108.25*scaleY,cellX=63*scaleX,cellY=63*scaleY,occupied=new Set<string>(),grid=imageFeature(bitmap,originX,originY,14*cellX+1.5*scaleX,14*cellY+1.5*scaleY,224,224);
     for(let row=0;row<14;row++)for(let col=0;col<14;col++){if(occupied.has(`${col}:${row}`)||cellDeviation(grid,col,row)<8)continue;const ranked:{t:typeof templates[number];score:number}[]=[];
       for(const t of templates){if(col+t.cols>14||row+t.rows>14)continue;ranked.push({t,score:regionMse(grid,224,t.feature,col*16,row*16,t.w,t.h)})}
       ranked.sort((a,b)=>a.score-b.score);const best=ranked[0],second=ranked[1];if(!best||best.score>1500||!second||second.score/best.score<1.18)continue;
       const confidence=Math.max(0,Math.min(99,Math.round((1-Math.sqrt(best.score)/255)*100)));const id=best.t.item.id;const prev=totals[id]||{count:0,confidence:100};totals[id]={count:prev.count+1,confidence:Math.min(prev.confidence,confidence)};for(let yy=0;yy<best.t.rows;yy++)for(let xx=0;xx<best.t.cols;xx++)occupied.add(`${col+xx}:${row+yy}`);
     }bitmap.close()}
   const result=Object.entries(totals).filter(([id])=>hideoutIds.has(id)).map(([id,v])=>({id,...v})).sort((a,b)=>b.count-a.count);setHits(result);setFileCount(images.length);setMessage(result.length?`${images.length}枚からハイドアウト素材 ${result.reduce((s,x)=>s+x.count,0)}個（${result.length}種類）を認識しました。その他のアイテムは除外済みです。`:"ハイドアウト用アイテムを認識できませんでした。ケース全体が見える1920×1080のスクショを使用してください。");
 }catch(e){console.error(e);setMessage("画像を読み取れませんでした。PNGまたはJPEGでもう一度お試しください。")}finally{setBusy(false)}};
 useEffect(()=>{const paste=(e:ClipboardEvent)=>{const files=[...(e.clipboardData?.files||[])];if(files.length)void analyze(files)};window.addEventListener("paste",paste);return()=>window.removeEventListener("paste",paste)},[]);
 const found=Object.fromEntries(hits.map(x=>[x.id,x.count]));
 const apply=(mode:"replace"|"add")=>{if(!hits.length)return;applyCounts(found,mode);setMessage(mode==="replace"?`ハイドアウト素材 ${hits.length}種類の所持数を更新しました。`:`ハイドアウト素材 ${hits.length}種類を現在の所持数へ加算しました。`)};
 return <section className="manager scanner"><div className="managerHead"><div><span>HIDEOUT / SCREENSHOT IMPORT</span><h2>スクショからハイドアウト素材を読取</h2><p>画像内の装備・武器・クエスト専用品などは除外し、ハイドアウト建設素材だけを反映します。</p></div></div><div className="scanGuide"><b>対応画面</b><span>1920×1080・アイテムケースを開いた状態・ケース全体が写っている画像</span><span>複数枚は一度に選択できます</span></div><div className={busy?"dropZone busy":"dropZone"} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();void analyze([...e.dataTransfer.files])}} onClick={()=>!busy&&input.current?.click()}><input ref={input} hidden type="file" accept="image/png,image/jpeg,image/webp" multiple onChange={e=>{void analyze([...(e.target.files||[])]);e.currentTarget.value=""}}/><strong>{busy?"ANALYZING…":"スクショをここへドロップ"}</strong><span>{busy?"画面を閉じずにお待ちください":"クリックして選択 / Ctrl+Vで貼り付け"}</span></div>{message&&<div className="scanMessage">{message}</div>}{hits.length>0&&<><div className="scanActions scanActionsSticky"><button type="button" onClick={()=>apply("replace")}>認識結果を所持数へ反映</button><button type="button" className="secondary" onClick={()=>apply("add")}>現在の所持数に加算</button><p>反映対象：ハイドアウト素材のみ（{hits.length}種類）</p></div><div className="scanResultHead"><div><small>HIDEOUT MATERIALS ONLY</small><h3>{fileCount}枚の認識結果</h3></div><span>数量をクリックして修正できます</span></div><div className="scanResults">{hits.map(hit=>{const item=hideoutItems.find(i=>i.id===hit.id)!;return <article key={hit.id}><img src={asset(`items/${hit.id}.webp`)} alt=""/><span><b>{item.shortName}</b><small>{item.name}</small></span><label><small>認識数</small><input type="number" min="0" value={hit.count} onChange={e=>setHits(old=>old.map(x=>x.id===hit.id?{...x,count:Math.max(0,Number(e.target.value)||0)}:x))}/></label><em>{hit.confidence}%</em></article>})}</div></>}</section>
}

type KeepMark={id:string;x:number;y:number;width:number;height:number;confidence:number};
function SellCheckPage({req}:{req:{q:Bag;h:Bag}}){
 const input=useRef<HTMLInputElement>(null),[useQuest,setUseQuest]=useState(true),[useHideout,setUseHideout]=useState(true),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[preview,setPreview]=useState(""),[marks,setMarks]=useState<KeepMark[]>([]),[imageSize,setImageSize]=useState({width:1920,height:1080});
 useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview]);
 const selectedNeeds=useMemo(()=>{const result:Bag={};for(const item of items){const count=(useQuest?(req.q[item.id]||0):0)+(useHideout?(req.h[item.id]||0):0);if(count>0)result[item.id]=count}return result},[req,useQuest,useHideout]);
 const analyze=async(file:File)=>{if(!useQuest&&!useHideout){setMessage("タスクまたはハイドアウトを選択してください。");return}setBusy(true);setMessage("スクショ内のアイテムを照合しています…");setMarks([]);const nextUrl=URL.createObjectURL(file);setPreview(old=>{if(old)URL.revokeObjectURL(old);return nextUrl});try{const bitmap=await createImageBitmap(file),scaleX=bitmap.width/1920,scaleY=bitmap.height/1080;setImageSize({width:bitmap.width,height:bitmap.height});const candidates=items.filter(item=>selectedNeeds[item.id]>0),templates=await Promise.all(candidates.map(async item=>{const img=await loadImage(asset(`items/${item.id}.webp`)),cols=Math.max(1,Math.round(img.naturalWidth/64)),rows=Math.max(1,Math.round(img.naturalHeight/64)),w=cols*16,h=rows*16;return{item,cols,rows,w,h,feature:imageFeature(img,0,0,img.naturalWidth,img.naturalHeight,w,h)}}));
   // The supported screenshot layout has one opened 14x14 container in the centre.
   // Scanning the stash/equipment panels as if they shared that grid caused empty
   // cells and closed containers to be marked, so keep the detector inside it.
   const regions=[{x:518,y:108,cols:14,rows:14}],rawMarks:KeepMark[]=[];
   for(const region of regions){const originX=region.x*scaleX,originY=region.y*scaleY,cellX=63*scaleX,cellY=63*scaleY;if(originX>=bitmap.width||originY>=bitmap.height)continue;const cols=Math.min(region.cols,Math.floor((bitmap.width-originX)/cellX)),rows=Math.min(region.rows,Math.floor((bitmap.height-originY)/cellY));if(cols<1||rows<1)continue;const grid=imageFeature(bitmap,originX,originY,cols*cellX,rows*cellY,cols*16,rows*16),occupied=new Set<string>();
    for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){if(occupied.has(`${col}:${row}`)||cellDeviationAt(grid,cols*16,col,row)<10)continue;const ranked:{t:typeof templates[number];score:number}[]=[];for(const t of templates){if(col+t.cols>cols||row+t.rows>rows)continue;const footprintCells=[];for(let yy=0;yy<t.rows;yy++)for(let xx=0;xx<t.cols;xx++)footprintCells.push(cellDeviationAt(grid,cols*16,col+xx,row+yy));const filled=footprintCells.filter(value=>value>=8).length/footprintCells.length;if(filled<.7)continue;ranked.push({t,score:regionMse(grid,cols*16,t.feature,col*16,row*16,t.w,t.h)})}ranked.sort((a,b)=>a.score-b.score);const best=ranked[0],second=ranked[1];if(!best||best.score>850||(second&&second.score/best.score<1.3))continue;const x=originX+col*cellX,y=originY+row*cellY,width=best.t.cols*cellX,height=best.t.rows*cellY,duplicate=rawMarks.some(mark=>mark.id===best.t.item.id&&Math.abs(mark.x-x)<cellX*.6&&Math.abs(mark.y-y)<cellY*.6);if(!duplicate)rawMarks.push({id:best.t.item.id,x,y,width,height,confidence:Math.max(0,Math.min(99,Math.round((1-Math.sqrt(best.score)/255)*100)))});for(let yy=0;yy<best.t.rows;yy++)for(let xx=0;xx<best.t.cols;xx++)occupied.add(`${col+xx}:${row+yy}`)}
   }
   const used:Bag={},limited=rawMarks.sort((a,b)=>a.y-b.y||a.x-b.x).filter(mark=>{const limit=selectedNeeds[mark.id]||0;if((used[mark.id]||0)>=limit)return false;used[mark.id]=(used[mark.id]||0)+1;return true});setMarks(limited);const types=new Set(limited.map(mark=>mark.id)).size;setMessage(limited.length?`${limited.length}枠（${types}種類）をKEEP対象として赤く表示しました。赤くないアイテムは選択条件では現在不要です。`:`必要アイテムを認識できませんでした。1920×1080でアイテム欄全体が見えるスクショを使用してください。`);bitmap.close()}catch(error){console.error(error);setMessage("画像を読み取れませんでした。PNGまたはJPEGでもう一度お試しください。")}finally{setBusy(false)}};
 const selectedLabel=useQuest&&useHideout?"タスク＋ハイドアウト":useQuest?"タスク":useHideout?"ハイドアウト":"未選択";
 return <section className="sellCheck"><header className="sellCheckHeader"><div><small>06 / STASH SELL SAFETY</small><h2>売却チェック</h2><p>赤いアイテムは現在必要です。売らずに残してください。</p></div><div className="keepLegend"><i></i><b>赤＝KEEP（売却しない）</b></div></header><section className="sellSettings"><div><small>CHECK TARGET</small><h3>判定対象を設定</h3><p>既存の完了タスクと設備レベルを自動的に反映します。</p></div><label className={useQuest?"checked":""}><input type="checkbox" checked={useQuest} onChange={event=>setUseQuest(event.target.checked)}/><span>✓</span><b>タスク</b><small>残り必要数 {Object.values(req.q).reduce((sum,count)=>sum+count,0)}</small></label><label className={useHideout?"checked":""}><input type="checkbox" checked={useHideout} onChange={event=>setUseHideout(event.target.checked)}/><span>✓</span><b>ハイドアウト</b><small>残り必要数 {Object.values(req.h).reduce((sum,count)=>sum+count,0)}</small></label></section><div className={busy?"sellDrop busy":"sellDrop"} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();const file=[...event.dataTransfer.files].find(candidate=>candidate.type.startsWith("image/"));if(file)void analyze(file)}} onClick={()=>!busy&&input.current?.click()}><input ref={input} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>{const file=event.target.files?.[0];if(file)void analyze(file);event.currentTarget.value=""}}/><strong>{busy?"ANALYZING…":"スタッシュのスクショを選択"}</strong><span>ドラッグ＆ドロップにも対応 · 現在の条件：{selectedLabel}</span></div>{message&&<div className="sellMessage">{message}</div>}{preview&&<section className="markedPreview"><header><div><small>KEEP RESULT</small><h3>売却前の確認画像</h3></div><b>{marks.length}枠 KEEP</b></header><div className="markedCanvas" style={{aspectRatio:`${imageSize.width}/${imageSize.height}`}}><img src={preview} alt="売却チェック対象のスタッシュ"/>{marks.map((mark,index)=>{const item=items.find(candidate=>candidate.id===mark.id);return <div className="keepMark" key={`${mark.id}-${index}`} style={{left:`${mark.x/imageSize.width*100}%`,top:`${mark.y/imageSize.height*100}%`,width:`${mark.width/imageSize.width*100}%`,height:`${mark.height/imageSize.height*100}%`}} title={`${item?.name||mark.id}：売却しない`}><span>KEEP</span></div>})}</div><footer><b>注意</b><span>赤い枠は設定した必要数まで表示します。装備品は判定対象外です。認識結果を確認してから売却してください。</span></footer></section>}</section>
}

