 const restored=useMemo(()=>{if(typeof window==="undefined")return{} as any;try{return JSON.parse(sessionStorage.getItem("tarkov-map-last-view")||"{}")}catch{return{} as any}},[]),initialCollapsed={PMC:true,Scav:true,All:true,Transit:true};
 const[selected,setSelected]=useState<any>(()=>mapStages.find(x=>x.name===(history.state?.mapStage||restored.selected))||null),[extract,setExtract]=useState<any>(restored.extract||null),[extractGuide,setExtractGuide]=useState<{images:Array<{url:string;caption:string}>;detail:string;sourceUrl:string;searchUrl:string;verified:boolean}|null>(null),[guideLoading,setGuideLoading]=useState(false),[latest,setLatest]=useState<any[]>([]),[loading,setLoading]=useState(true),[collapsedGroups,setCollapsedGroups]=useState<Record<string,boolean>>({...initialCollapsed,...(restored.collapsedGroups||{})});
 useEffect(()=>{window.stashAI?.maps?.().then(data=>setLatest(Array.isArray(data)?data:[])).catch(()=>{}).finally(()=>setLoading(false))},[]);
 useEffect(()=>{sessionStorage.setItem("tarkov-map-last-view",JSON.stringify({selected:selected?.name||"",extract:extract||null,collapsedGroups}))},[selected,extract,collapsedGroups]);
 useEffect(()=>{const restore=(event:PopStateEvent)=>{if(event.state?.stashPage==="maps"){setSelected(mapStages.find(x=>x.name===event.state?.mapStage)||null);setExtract(null)}};window.addEventListener("popstate",restore);return()=>window.removeEventListener("popstate",restore)},[]);
 useEffect(()=>{let cancelled=false;setExtractGuide(null);if(extract&&selected&&window.stashAI?.extractGuide){setGuideLoading(true);window.stashAI.extractGuide(selected.name,extract.name).then(guide=>{if(!cancelled)setExtractGuide(guide)}).catch(()=>{if(!cancelled)setExtractGuide(null)}).finally(()=>{if(!cancelled)setGuideLoading(false)})}return()=>{cancelled=true}},[extract?.name,selected?.name]);
 const openStage=(stage:any)=>{history.pushState({...history.state,stashPage:"maps",mapStage:stage.name},"");setSelected(stage);setExtract(null);setCollapsedGroups(initialCollapsed)};
 const mapKey=(value:any)=>String(value||"").toLowerCase().replace(/^the\s+/,"").replace(/[^a-z0-9]/g,""),source=selected&&latest.find(x=>String(x.id||"")===String(selected.id||"__missing__")||mapKey(x.name)===mapKey(selected.name)||mapKey(x.normalizedName)===mapKey(selected.name)),liveExtracts=source?.extracts||[],extracts=selected?.name==="Factory"?factoryExtracts:liveExtracts,transits=selected?.name==="Factory"?[]:(source?.transits||[]),groups=[{key:"PMC",title:"PMC専用",className:"pmc",items:extracts.filter((x:any)=>/^pmc$/i.test(x.faction))},{key:"Scav",title:"SCAV専用",className:"scav",items:extracts.filter((x:any)=>/scav/i.test(x.faction))},{key:"All",title:"PMC・SCAV共通",className:"both",items:extracts.filter((x:any)=>/all|both/i.test(x.faction))},{key:"Transit",title:"他マップへのトランジット",className:"transit",items:transits}];
 if(selected)return <section className="mapHub mapDetail"><button className="mapBack" onClick={()=>{setSelected(null);setExtract(null)}}>← 全マップへ戻る</button><header><div><small>LOCATION GUIDE</small><h2>{selected.ja}<span>{selected.name}</span></h2><p>{selected.desc}</p></div><div><b>{selected.name==="Factory"||liveExtracts.length?"最新データ確認済み":"最新情報を取得できません"}</b><small>{source?.players&&`PMC ${source.players}`}</small><small>{source?.raidDuration&&`制限時間 ${source.raidDuration}分`}</small></div></header><div className="mapInfoLayout"><div className="mapLarge"><img src={mapImageFor({id:selected.id,name:selected.name,slug:selected.name.toLowerCase().replace(/\s+/g,"-")})} alt={`${selected.name} map`}/><div><b>初心者向け確認ポイント</b><span>出撃地点を確認したら、最初に大きな建物・道路・地形から現在地を特定してください。</span><span>脱出地点は所属と出撃位置によって利用可否が変わります。レイド中にOキーを2回押して確認します。</span></div></div><aside className="extractPanel grouped"><h3>脱出地点 <small>{extracts.length}か所{transits.length?` ＋ トランジット${transits.length}か所`:""}</small></h3><div className="extractLegend"><span className="pmc">PMC専用</span><span className="scav">SCAV専用</span><span className="both">共通</span></div>{loading&&selected.name!=="Factory"&&<p>最新の脱出地点を確認中…</p>}{groups.map(group=>group.items.length?<section className={`extractGroup ${group.className} ${collapsedGroups[group.key]?"collapsed":""}`} key={group.key}><button type="button" className="extractGroupToggle" aria-expanded={!collapsedGroups[group.key]} onClick={()=>setCollapsedGroups(old=>({...old,[group.key]:!old[group.key]}))}><b>{group.title}</b><span>{group.items.length}か所</span><i>{collapsedGroups[group.key]?"＋":"−"}</i></button>{!collapsedGroups[group.key]&&group.items.map((x:any,index:number)=><button key={`${x.name}-${index}`} onClick={()=>setExtract(x)}><i></i><span><strong>{x.name}</strong><small>{x.direction||x.requirement||x.faction}</small></span><b>›</b></button>)}</section>:null)}{!loading&&selected.name!=="Factory"&&!liveExtracts.length&&<p className="mapDataError">最新データを取得できませんでした。インターネット接続を確認してアプリを再起動してください。古い3件だけを正しい一覧としては表示しません。</p>}</aside></div>{extract&&<div className="extractModal" onClick={()=>setExtract(null)}><article onClick={e=>e.stopPropagation()}><button onClick={()=>setExtract(null)}>×</button><small>{extract.kind==="transit"?"TRANSIT POINT":"EXTRACTION POINT"} · {extract.faction}</small><h2>{extract.name}</h2><div className="extractFacts"><span><small>方角・階層</small><b>{extract.direction||"マップ画像で確認"}</b></span><span><small>利用条件</small><b>{extract.requirement||"レイド内の脱出一覧で確認"}</b></span></div><div className="extractVisualGuide"><b>画像でたどる脱出ルート</b><span>①マップ上の位置 → ②周辺の目印 → ③入口 → ④脱出判定地点の順に確認してください</span></div><div className="extractGuideImages">{[...(extract.image?[{url:extract.image,caption:`${extract.name} 現地画像`}]:[]),...(extractGuide?.images||[])].filter((image:any,index:number,list:any[])=>list.findIndex(x=>x.url===image.url)===index).slice(0,4).map((image:any,index:number)=><a href={image.url} target="_blank" rel="noreferrer" key={`${image.url}-${index}`}><i>{String(index+1).padStart(2,"0")}</i><img src={image.url} alt={`${extract.name}の現地参考画像 ${index+1}`}/><span>{image.caption||`${extract.name} 参考画像 ${index+1}`}<small>クリックして原寸表示</small></span></a>)}</div>{guideLoading&&<p className="extractGuideLoading">現地画像をネットから検索しています…</p>}{!guideLoading&&!extract.image&&!extractGuide?.images.length&&<p className="extractGuideMissing">脱出地点名との一致を確認できる画像が見つからなかったため、無関係な画像は表示していません。下の画像検索から確認できます。</p>}<div className="extractGuideLinks">{extractGuide?.sourceUrl&&<a href={extractGuide.sourceUrl} target="_blank" rel="noreferrer">Wikiでこの脱出地点を確認 ↗</a>}{extractGuide?.searchUrl&&<a href={extractGuide.searchUrl} target="_blank" rel="noreferrer">現地画像を検索 ↗</a>}</div><div><b>現地の見分け方</b><p>{extract.description||extractGuide?.detail||"マップ上の脱出地点名と、ゲーム内でOキーを2回押したときの名称を照合してください。画像の入口・扉・車両・照明などを目印にしてください。"}</p></div></article></div>}</section>;
