  <section className="objectiveSection"><div className="detailTitle"><small>STEP BY STEP</small><h3>達成手順・目的地点</h3></div>{task.objectives.map((objective:any,index:number)=>{const description=jp(objective.descriptionJa,objective.description);return <div className="objectiveCard" key={objective.id}><b>{String(index+1).padStart(2,"0")}</b><div><small>{objectiveLabel[objective.type]||objective.type}{objective.count>1?` ×${objective.count}`:""}{objective.foundInRaid?" · FIR":""}</small><h4>{description}</h4>{description!==objective.description&&<p>{objective.description}</p>}{objective.maps?.length>0&&<div className="mapTags">{objective.maps.map((map:any)=>{const zone=objective.zones?.find((z:any)=>z.map===map.id&&z.position)||objective.zones?.find((z:any)=>z.position)||task.objectives.flatMap((x:any)=>x.zones||[]).find((z:any)=>z.map===map.id&&z.position);return <button type="button" className="mapOpenButton" key={map.id||map.name} onClick={()=>openObjectiveMap(map,zone,objective,description)}>⌖ MAP · {map.nameJa||map.name}</button>})}{task.wiki&&<a className="taskSpecificMap" href={task.wiki} target="_blank" rel="noreferrer">このタスク専用の攻略画像 ↗</a>}</div>}{objective.zones?.some((zone:any)=>zone.position)&&<div className="zoneCoordinates">{objective.zones.filter((zone:any)=>zone.position).slice(0,3).map((zone:any)=><span key={`${zone.id}-${zone.map}`}>目的地点座標　X {zone.position.x.toFixed(1)} / Z {zone.position.z.toFixed(1)}</span>)}</div>}{objective.items?.length>0&&<div className="guideItems">{objective.items.map((item:any)=><div key={item.id}><img src={item.image||`https://assets.tarkov.dev/${item.id}-grid-image.webp`} onError={e=>{const img=e.currentTarget;if(!img.dataset.fallback){img.dataset.fallback="1";img.src=asset(`items/${item.id}.webp`)}}} alt={item.name||item.shortName||"アイテム"}/><span><strong>{item.nameJa||item.shortName||item.name}</strong><small>{item.name}</small></span></div>)}</div>}</div></div>})}</section>
