function WeaponBuildGuide({builds,loading,verified,wiki}:{builds:any[];loading:boolean;verified:boolean;wiki:string}){
 const labels:Record<string,string>={Ergonomics:"エルゴノミクス",Recoil:"反動",VerticalRecoil:"垂直反動",HorizontalRecoil:"水平反動",Weight:"重量",Durability:"耐久値",MagazineCapacity:"マガジン装弾数",SightingRange:"照準距離",MuzzleVelocity:"初速",Accuracy:"精度"},comparison=(method:string,value:number)=>{const operators:Record<string,string>={">=":"以上","=>":"以上","more":"以上","<":"未満","<=":"以下","=<":"以下","less":"以下","=":"ちょうど"};return `${Number(value).toLocaleString()} ${operators[method]||method||""}`.trim()};
 if(loading)return <section className="weaponBuildGuide"><div className="weaponBuildLoading"><i></i><b>最新の改造条件を取得中…</b><span>ベース武器・必須パーツ・性能条件を確認しています</span></div></section>;
 if(!builds.length)return <section className="weaponBuildGuide"><header><small>WEAPON BUILD</small><h3>武器改造ガイド</h3></header><div className="weaponBuildUnavailable"><b>{verified?"このタスクには取得できる改造条件がありません":"改造条件を取得できませんでした"}</b><p>ネット接続後にページを開き直すか、下の攻略ページで現在の条件を確認してください。</p>{wiki&&<a href={wiki} target="_blank" rel="noreferrer">最新の改造条件を確認 ↗</a>}</div></section>;
 return <section className="weaponBuildGuide"><header><small>WEAPON BUILD</small><h3>具体的な改造内容</h3><p>上から順に用意し、最後に性能値を確認してください。</p></header>{builds.map((build,index)=><article className="weaponBuildCard" key={build.id||index}><div className="weaponBase"><span>STEP 1　ベース武器</span>{build.item&&<><img src={build.item.inspectImageLink||build.item.gridImageLink||`https://assets.tarkov.dev/${build.item.id}-grid-image.webp`} alt=""/><div><strong>{build.item.name||build.item.shortName}</strong><small>{build.item.shortName}</small></div></>}</div><div className="weaponParts"><h4>STEP 2　取り付ける必須パーツ</h4>{build.parts?.length?<div>{build.parts.map((part:any)=><article key={part.id}><img src={part.gridImageLink||`https://assets.tarkov.dev/${part.id}-grid-image.webp`} alt=""/><span><b>{part.name||part.shortName}</b><small>{part.shortName}</small></span></article>)}</div>:<p>個別指定の必須パーツはありません。</p>}{build.categories?.length>0&&<div className="weaponCategories"><b>種類指定</b>{build.categories.map((category:any)=><span key={category.id}>{category.name}</span>)}</div>}</div><div className="weaponStats"><h4>STEP 3　完成後の性能条件</h4>{build.attributes?.length?<div>{build.attributes.map((attribute:any)=><span key={attribute.name}><small>{labels[attribute.name]||attribute.name}</small><strong>{comparison(attribute.requirement?.compareMethod,attribute.requirement?.value)}</strong></span>)}</div>:<p>数値条件はありません。必須パーツが装着されていることを確認してください。</p>}</div><footer><b>STEP 4</b><span>武器の耐久・折り畳み状態・弾薬やマガジンを含めて条件を再確認し、Mechanicへ納品します。</span></footer></article>)}</section>
}
