function Search({value,set}:{value:string,set:(v:string)=>void}){return <label className="search"><span>⌕</span><input value={value} onChange={e=>set(e.target.value)} placeholder="名前で検索…"/></label>}
function ItemPage({query,setQuery,visible,req,counts,setCount}:{query:string,setQuery:(v:string)=>void,visible:typeof items,req:{q:Bag,h:Bag},counts:Bag,setCount:(id:string,n:number)=>void}){return <><section className="toolbar simple"><div><b>ALL REQUIRED ITEMS</b><span>所持数を入力すると、不足・達成状況を自動計算します</span></div><Search value={query} set={setQuery}/></section><div className="listHeader"><span>{visible.length} ITEMS</span><span>必要 / 所持 / 不足・余り</span></div><section className="grid itemTotals ownedGrid">{visible.map(i=>{const quest=req.q[i.id]||0,hideout=req.h[i.id]||0,need=quest+hideout,have=counts[i.id]||0,diff=have-need,complete=diff>=0;return <article className={complete?"card totalCard ownershipCard completeOwned":"card totalCard ownershipCard"} key={i.id}><div className="imageWrap"><img src={asset(`items/${i.id}.webp`)} alt=""/></div><div className="itemInfo"><h2>{i.shortName}</h2><p>{i.name}</p><div className="tags">{quest>0&&<span className="quest">Q {quest}</span>}{hideout>0&&<span className="hideout">H {hideout}</span>}{i.foundInRaid&&<span className="fir">FIR</span>}</div></div><div className="ownershipNumbers"><div className="needNumber"><span>必要</span><strong>{need}</strong></div><label className="ownedInput"><span>所持</span><input type="number" min="0" value={have} onChange={e=>setCount(i.id,Number(e.target.value)||0)} aria-label={`${i.name}の所持数`}/></label><div className={complete?"difference surplus":"difference shortage"}><span>{complete?"余り":"不足"}</span><strong>{complete?`+${diff}`:Math.abs(diff)}</strong></div></div></article>})}</section>{!visible.length&&<div className="empty">残っている必要アイテムはありません。</div>}</>}

function QuestPage({query,setQuery,done,setDone,storyDone,setStoryDone}:{query:string,setQuery:(v:string)=>void,done:Checks,setDone:(v:Checks)=>void,storyDone:Checks,setStoryDone:(v:Checks)=>void}){const[open,setOpen]=useState("Prapor"),matches=(s:string)=>s.toLowerCase().includes(query.toLowerCase());return <section className="manager"><ManagerHead code="02 / QUESTS" title="クエスト進捗" text="完了すると関連アイテムが必要数から差し引かれます。" query={query} setQuery={setQuery}/><div className="storyPanel"><div><small>MAIN STORY</small><h3>メインクエスト</h3></div><div className="storyGrid">{progress.story.filter(matches).map(name=><CheckRow key={name} checked={!!storyDone[name]} onChange={v=>setStoryDone({...storyDone,[name]:v})} title={name} meta="STORY CHAPTER"/>)}</div></div><div className="sectionLabel">SUB QUESTS · トレーダー別</div><div className="traderList">{traders.map(trader=>{const list=progress.quests.filter(q=>q.trader===trader&&matches(q.name));if(!list.length)return null;const complete=list.filter(q=>done[q.id]).length,expanded=open===trader||!!query;return <div className="trader" key={trader}><button className="traderHead" onClick={()=>setOpen(expanded?"":trader)}><strong>{trader}</strong><span>{complete} / {list.length} 完了</span><i>{expanded?'−':'＋'}</i></button>{expanded&&<div className="questRows">{list.map(q=><CheckRow key={q.id} checked={!!done[q.id]} onChange={v=>setDone({...done,[q.id]:v})} title={q.name} meta={`LV ${q.level} · 納品 ${q.items.reduce((s,x)=>s+x.count,0)}個`}/>)}</div>}</div>})}</div></section>}
function ManagerHead({code,title,text,query,setQuery}:{code:string,title:string,text:string,query:string,setQuery:(v:string)=>void}){const resetTarget=code.startsWith("02")?"quests":code.startsWith("03")?"owned":"",resetLabel=resetTarget==="owned"?"所持数をリセット":"すべてリセット";return <div className="managerHead"><div><span>{code}</span><h2>{title}</h2><p>{text}</p></div><div className="managerActions"><Search value={query} set={setQuery}/>{resetTarget&&<button className="resetButton" onClick={()=>window.dispatchEvent(new CustomEvent("ledger-reset",{detail:resetTarget}))}><span>↺</span> {resetLabel}</button>}</div></div>}
function CheckRow({checked,onChange,title,meta}:{checked:boolean,onChange:(v:boolean)=>void,title:string,meta:string}){return <label className={checked?"checkRow checked":"checkRow"}><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><span className="box">✓</span><span><strong>{title}</strong><small>{meta}</small></span></label>}

function HideoutWorkspace({query,setQuery,done,setLevel,counts,applyCounts}:{query:string,setQuery:(v:string)=>void,done:Checks,setLevel:(s:string,l:number)=>void,counts:Bag,applyCounts:(found:Bag,mode:"replace"|"add")=>void}){const[section,setSection]=useState<"progress"|"scan">("progress");return <><div className="hideoutSubnav"><button className={section==="progress"?"active":""} onClick={()=>setSection("progress")}><span>01</span> 設備進捗</button><button className={section==="scan"?"active":""} onClick={()=>setSection("scan")}><span>02</span> スクショ取込</button></div>{section==="progress"?<HideoutPage query={query} setQuery={setQuery} done={done} setLevel={setLevel} counts={counts}/>:<ScanPage counts={counts} applyCounts={applyCounts}/>}</>}

function HideoutPage({query,setQuery,done,setLevel,counts}:{query:string,setQuery:(v:string)=>void,done:Checks,setLevel:(s:string,l:number)=>void,counts:Bag}){
 const [settingsOpen,setSettingsOpen]=useState(false),all=[...new Set(progress.modules.map(m=>m.station))],stations=all.filter(s=>(ja[s]+s).toLowerCase().includes(query.toLowerCase()));
 const currentNeeds=useMemo(()=>{const result:Bag={};for(const station of all){const levels=progress.modules.filter(m=>m.station===station).sort((a,b)=>a.level-b.level),current=Math.max(0,...levels.filter(m=>done[m.id]).map(m=>m.level)),next=levels.find(m=>m.level>current);if(next)for(const material of next.items)result[material.id]=(result[material.id]||0)+material.count}return result},[done]);
 const needItems=items.filter(item=>(currentNeeds[item.id]||0)>0).sort((a,b)=>Math.max(0,(currentNeeds[b.id]||0)-(counts[b.id]||0))-Math.max(0,(currentNeeds[a.id]||0)-(counts[a.id]||0))||a.shortName.localeCompare(b.shortName));
 return <section className="manager">
  <ManagerHead code="03 / HIDEOUT" title="ハイドアウト" text="現在完成しているレベルを設定すると、次に必要な素材だけを表示します。" query={query} setQuery={setQuery}/>
  <section className={settingsOpen?"hideoutSettings open":"hideoutSettings collapsed"}>
   <div className="settingsTitle"><button type="button" className="settingsToggle" onClick={()=>setSettingsOpen(v=>!v)} aria-expanded={settingsOpen}><span>⚙</span><div><small>LEVEL SETTINGS</small><h3>現在の設備レベルを設定</h3><p>{settingsOpen?"設定を閉じる":"クリックして設備レベル設定を開く"}</p></div><b>{settingsOpen?"▲":"▼"}</b></button>{settingsOpen&&<button className="resetButton levelResetButton" onClick={()=>window.dispatchEvent(new CustomEvent("ledger-reset",{detail:"hideout-levels"}))}><span>↺</span> 設備レベルをリセット</button>}</div>
   {settingsOpen&&<div className="settingsGrid">{all.map(station=>{const levels=progress.modules.filter(m=>m.station===station),current=Math.max(0,...levels.filter(m=>done[m.id]).map(m=>m.level));return <label key={station}><span>{ja[station]||station}</span><select value={current} onChange={e=>setLevel(station,Number(e.target.value))}><option value="0">未建設</option>{levels.map(m=><option value={m.level} key={m.id}>Lv.{m.level} 完成</option>)}</select></label>})}</div>}
  </section>
  <section className="hideoutNeedOverview"><div className="overviewHead"><div><small>CURRENT TOTAL REQUIREMENTS</small><h3>現在のハイドアウト必要素材一覧</h3><p>各設備の次レベルに必要な素材を、アイテム別に合算しています。</p></div><strong>{needItems.length}<small>種類</small></strong></div><div className="overviewItems">{needItems.map(item=>{const need=currentNeeds[item.id]||0,owned=counts[item.id]||0,shortage=Math.max(0,need-owned),enough=shortage===0;return <article className={enough?"overviewEnough":"overviewShort"} key={item.id}><img src={asset(`items/${item.id}.webp`)} alt=""/><span><b>{item.shortName}</b><small>{item.name}</small></span><div><small>所持 / 必要</small><strong>{owned}<i>/</i>{need}</strong><em>{enough?"準備完了":`不足 ${shortage}`}</em></div></article>})}</div></section>
  <div className="sectionDivider"><span>EQUIPMENT BREAKDOWN</span></div>
  <div className="sectionLabel">設備種目別 · 次のレベルで必要なアイテム</div>
  <div className="hideoutModules">{stations.map(station=>{const levels=progress.modules.filter(m=>m.station===station).sort((a,b)=>a.level-b.level),current=Math.max(0,...levels.filter(m=>done[m.id]).map(m=>m.level)),next=levels.find(m=>m.level>current),sid=levels[0]?.stationId;return <article className="moduleCard" key={station}><div className="moduleVisual"><img src={asset(`hideout/${sid}.png`)} alt=""/><div><small>HIDEOUT MODULE</small><h3>{ja[station]||station}</h3><p>{station}</p></div><div className="levelBadge"><span>現在</span><b>{current?`LV.${current}`:'未建設'}</b><i>→</i><span>次</span><b>{next?`LV.${next.level}`:'MAX'}</b></div></div>{next?<><div className="nextSummary"><span>Lv.{next.level} に必要</span><strong>{next.items.reduce((s,x)=>s+x.count,0)}</strong><small>個 / {next.items.length}種類</small></div><div className="upgradeItems">{next.items.map(x=>{const item=items.find(i=>i.id===x.id),owned=counts[x.id]||0,enough=owned>=x.count;return <div className={enough?"materialEnough":"materialShort"} key={x.id}><img src={asset(`items/${x.id}.webp`)} alt=""/><span><b>{item?.shortName||x.id}</b><small>{item?.name}</small></span><div className="ownedNeed"><small>所持 / 必要</small><strong>{owned}<i>/</i>{x.count}</strong><em>{enough?"準備完了":`不足 ${x.count-owned}`}</em></div></div>})}</div></>:<div className="moduleComplete">✓ すべてのレベルが完成しています</div>}</article>})}</div>
 </section>
}
